mapper.insert:
insert into tbl_board_comment (comment_seq, board_seq, member_seq, content)
	select seq_board_comment.nextval, #{boardSeq}, #{memberSeq}, #{content}
		from tbl_board b
			where b.board_seq = #{boardSeq}
				and b.enabled = 'Y'

mapper.update:
update tbl_board_comment
	set content = #{content},
		moddate = sysdate
			where comment_seq = #{commentSeq}
				and member_seq = #{memberSeq}
				and enabled = 'Y'

update tbl_board_comment
	set enabled = 'N'
		where comment_seq = #{commentSeq}
			and member_seq = #{memberSeq}
			and enabled = 'Y'
